    function openCode(id) {
      var body = document.getElementById(id + '_body');
      bootstrap.Collapse.getOrCreateInstance(body, {toggle: false}).show();
      var box = document.getElementById(id + '_box');
      box.scrollIntoView({behavior: 'smooth', block: 'start'});
      box.classList.remove('flash'); void box.offsetWidth; box.classList.add('flash');
    }
    function copyCode(id, btn) {
      var text = document.getElementById(id + '_edit').value;
      var done = function() { var old = btn.innerHTML; btn.innerHTML = 'Copied!';
                              setTimeout(function() { btn.innerHTML = old; }, 1500); };
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(done);
      } else {
        var ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta);
        ta.select(); document.execCommand('copy'); document.body.removeChild(ta); done();
      }
    }
    document.addEventListener('shown.bs.collapse', function(e) {
      var b = document.querySelector('[data-bs-target=\"#' + e.target.id + '\"] .label');
      if (b) b.textContent = ' Hide the code';
      $(e.target).trigger('shown');   // tell Shiny the code is now visible
    });
    // Scroll to a section and flash it
    // Measuring buttons: drive the map's ruler tool directly, so it works without hovering (tablets, touch screens)
    function measureCtl(sel) { return document.querySelector('#map .leaflet-control-measure ' + sel); }
    function measureStatus(msg) { var s = document.getElementById('meas_status'); if (s) s.textContent = msg; }
    function measureStart() {
      var start = measureCtl('.js-start');
      if (!start) { measureStatus('The map is still loading. Try again in a moment.'); return; }
      start.click();
      document.getElementById('map').scrollIntoView({behavior: 'smooth', block: 'center'});
      measureStatus('Measuring: tap or click points around the island edge (or two points for a distance), then press Finish.');
    }
    function measureFinish() {
      var fin = measureCtl('.js-finish');
      if (fin) fin.click();
      measureStatus('Done. Read the area (or distance) in the box on the map and type it in step 3.');
    }
    function jumpTo(id) {
      var el = document.getElementById(id);
      el.scrollIntoView({behavior: 'smooth', block: 'start'});
      el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash');
    }
    $(document).on('shiny:connected', function() {
      Shiny.addCustomMessageHandler('flash', function(id) {
        var el = document.getElementById(id);
        if (el) { el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash'); }
      });
    });
    // Code editor grows to fit its code, so students never have to scroll inside it
    function autoSizeCode(ta) {
      if (!ta || !ta.classList || !ta.classList.contains('code-editor')) return;
      // refresh the coloured copy of the code behind the editor
      var pre = ta.parentNode && ta.parentNode.querySelector('.code-hl');
      if (pre && window.highlightR) pre.innerHTML = window.highlightR(ta.value) + String.fromCharCode(10);
      if (ta.offsetParent === null) return;
      ta.style.height = 'auto'; ta.style.height = (ta.scrollHeight + 4) + 'px';
    }
    document.addEventListener('input', function(e) { autoSizeCode(e.target); });
    $(document).on('shiny:updateinput', function(e) { setTimeout(function() { autoSizeCode(e.target); }, 0); });
    document.addEventListener('shown.bs.collapse', function(e) { autoSizeCode(e.target.querySelector('.code-editor')); });
    // Send exactly what is in the editor right now to R
    function runCode(id) {
      var code = document.getElementById(id + '_edit').value;
      Shiny.setInputValue(id + '_submit', {code: code, t: Date.now()}, {priority: 'event'});
    }
    // In the code editor: Tab inserts spaces, Ctrl/Cmd + Enter runs the code
    document.addEventListener('keydown', function(e) {
      var ta = e.target;
      if (!ta.classList || !ta.classList.contains('code-editor')) return;
      if (e.key === 'Tab') {
        e.preventDefault();
        var s = ta.selectionStart;
        ta.value = ta.value.slice(0, s) + '  ' + ta.value.slice(ta.selectionEnd);
        ta.selectionStart = ta.selectionEnd = s + 2;
        $(ta).trigger('change'); autoSizeCode(ta);
      } else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        runCode(ta.id.replace(/_edit$/, ''));
      }
    });
    document.addEventListener('hidden.bs.collapse', function(e) {
      var b = document.querySelector('[data-bs-target=\"#' + e.target.id + '\"] .label');
      if (b) b.textContent = ' Show the code';
    });
  "))
)

# ---- Colour highlighting for the R code boxes --------------------------------
# Splits R code into parts (comments, "text", numbers, function names, argument names,
# operators, TRUE/FALSE/NULL...) and wraps each in a coloured <span>. Colours are set in the CSS (.hl-*).
code_highlight_js <- tags$head(tags$script(HTML(r"---(
  (function() {
    var KEYWORDS = /^(TRUE|FALSE|NULL|NA|NaN|Inf|function|if|else|for|while|in|return)$/;
    function esc(s) { return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
    window.highlightR = function(src) {
      var re = /(#[^\n]*)|("(?:[^"\\\n]|\\.)*"?|'(?:[^'\\\n]|\\.)*'?)|(`[^`\n]*`?)|(\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|([A-Za-z.][A-Za-z0-9._]*)|(<-|\|>|%>%|%in%|==|!=|<=|>=|[~+$*\/^=!&|<>-])/g;
      var out = '', last = 0, m;
      while ((m = re.exec(src)) !== null) {
        out += esc(src.slice(last, m.index));
        var t = m[0], cls = null;
        if (m[1]) cls = 'hl-com';
        else if (m[2]) cls = 'hl-str';
        else if (m[3]) cls = 'hl-bt';
        else if (m[4]) cls = 'hl-num';
        else if (m[5]) {
          var rest = src.slice(re.lastIndex);
          if (KEYWORDS.test(t)) cls = 'hl-kw';
          else if (/^\s*\(/.test(rest)) cls = 'hl-fun';
          else if (/^\s*=(?!=)/.test(rest)) cls = 'hl-arg';
        }
        else if (m[6]) cls = 'hl-op';
        out += cls ? '<span class="' + cls + '">' + esc(t) + '</span>' : esc(t);
        last = re.lastIndex;
      }
      return out + esc(src.slice(last));
    };
  })();
)---")))

# ---- R code shown in the "See the R code" panels ---------------------------
# Base read.csv() plus tidyverse packages (dplyr, tibble, ggplot2). Each function returns the code as text.
# S, A, X are the chosen column names (already wrapped in `backticks` if needed);
# read_line is the line that reads the data, e.g. islands <- read.csv("data/hakai_100_islands.csv").
code_text <- function(...) paste(c(...), collapse = "\n")

code_map_txt <- function(read_line, lon, lat, label) code_text(
  "# Lines starting with # are comments: notes for people. R skips them.",
  "",
  "# Load the leaflet package, which draws interactive maps",
  "library(leaflet)",
  "",
  "# Read the spreadsheet of islands and store it under the name 'islands'.",
  "# The data are tidy: one row per island, one column per variable.",
  read_line,
  "",
  "# Build the map one layer at a time. The |> symbol (the 'pipe') means",
  "# 'take the result so far and pass it to the next step'.",
  "leaflet(islands) |>",
  "  # 1. a satellite photo background",
  "  addProviderTiles(providers$Esri.WorldImagery) |>",
  "  # 2. one circle per island, placed by its longitude (lng) and latitude (lat);",
  "  #    ~ means 'use this column of islands'. radius sets the circle size.",
  sprintf("  addCircleMarkers(lng = ~%s, lat = ~%s,", lon, lat),
  sprintf("                   label = ~%s, radius = 6) |>", label),
  "  # 3. the ruler tool, reporting distances in metres and areas in square metres",
  "  addMeasure(primaryLengthUnit = \"meters\", primaryAreaUnit = \"sqmeters\")"
)

code_data_txt <- function(read_line, S, A) code_text(
  "# Lines starting with # are comments: notes for people. R skips them.",
  "",
  "# Load dplyr, a tidyverse package with tools for working with tidy data",
  "library(dplyr)",
  "",
  "# Read the spreadsheet (a .csv file) and store it under the name 'islands'.",
  "# The <- arrow means 'store the result on the right under the name on the left'.",
  read_line,
  "",
  "# These data are 'tidy': each row is one island (one observation),",
  "# each column is one variable, and each cell holds one value.",
  "# glimpse() lists every column with its type and its first few values.",
  "glimpse(islands)",
  "",
  "# summarise() boils the whole table down to one row of summary numbers.",
  "# n() counts the rows; na.rm = TRUE skips missing values.",
  "islands |>",
  "  summarise(",
  "    number_of_islands = n(),",
  sprintf("    smallest_area     = min(%s, na.rm = TRUE),", A),
  sprintf("    largest_area      = max(%s, na.rm = TRUE),", A),
  sprintf("    mean_species      = mean(%s, na.rm = TRUE)", S),
  "  )"
)

code_sa_txt <- function(read_line, S, A, loglog = TRUE) code_text(
  "# Lines starting with # are comments: notes for people. R skips them.",
  "",
  "# Load the tidyverse packages: dplyr wrangles data, ggplot2 draws graphs",
  "library(dplyr)",
  "library(ggplot2)",
  "",
  "# Read the spreadsheet into R and call it 'islands' (one row per island)",
  read_line,
  "",
  "# filter() keeps only the rows (islands) that meet a condition.",
  "# Keep islands with more than 0 species and an area above 0,",
  "# because the log of 0 cannot be calculated.",
  "islands <- islands |>",
  sprintf("  filter(%s > 0, %s > 0)", S, A),
  "",
  "# Fit the species-area model as a straight line on log-log axes:",
  "#   log10(S) = log10(c) + z * log10(A)",
  "# lm() fits a straight line ('linear model'); y ~ x means 'y explained by x'.",
  sprintf("model <- lm(log10(%s) ~ log10(%s), data = islands)", S, A),
  "",
  "# Print the full results. The 'Estimate' for log10(area) is z, the slope.",
  "summary(model)",
  "",
  "# Collect the key numbers in a small tidy table: one row, one column per number.",
  "# coef(model) gives [1] the intercept and [2] the slope (z);",
  "# the intercept is log10(c), so 10^ turns it back into c.",
  "results <- tibble(",
  "  z                 = coef(model)[2],",
  "  c                 = 10^coef(model)[1],",
  "  r_squared         = summary(model)$r.squared,",
  "  number_of_islands = nrow(islands)",
  ")",
  "results",
  "",
  if (!loglog) c(
    "# On ordinary axes the fitted relationship S = c * A^z is a curve.",
    "# Make a small table of 200 areas from smallest to largest, then use",
    "# mutate() to add the species number the model predicts for each one.",
    "curve_points <- tibble(",
    sprintf("  area = seq(min(islands$%s), max(islands$%s), length.out = 200)", A, A),
    ") |>",
    "  mutate(species = results$c * area^results$z)",
    ""
  ),
  "# Draw the graph with ggplot2: start from the data, map columns to the",
  "# x and y axes with aes(), then add layers one at a time with +.",
  sprintf("ggplot(islands, aes(x = %s, y = %s)) +", A, S),
  "  geom_point(colour = \"#C55A11\", size = 2.5) +     # one dot per island",
  if (loglog) c(
    "  geom_smooth(method = \"lm\", formula = y ~ x,     # the fitted straight line",
    "              se = FALSE, colour = \"#6B2E0A\") +",
    "  scale_x_log10() +                               # log scale on the x-axis",
    "  scale_y_log10() +                               # log scale on the y-axis"
  ) else c(
    "  # the fitted curve, drawn through the predicted points",
    "  geom_line(data = curve_points, aes(x = area, y = species),",
    "            colour = \"#6B2E0A\", linewidth = 1) +"
  ),
  "  labs(x = \"Island area\", y = \"Number of species\") +",
  "  theme_classic(base_size = 14)"
)

code_resid_txt <- function(read_line, S, A, X, logx = TRUE) code_text(
  "# Lines starting with # are comments: notes for people. R skips them.",
  "",
  "library(dplyr)",
  "library(ggplot2)",
  "",
  "# Read the data and keep islands with species and area above 0 (log of 0 is impossible)",
  read_line,
  "islands <- islands |>",
  sprintf("  filter(%s > 0, %s > 0)", S, A),
  "",
  "# Fit the species-area line, as on the Species-Area tab",
  sprintf("model <- lm(log10(%s) ~ log10(%s), data = islands)", S, A),
  "",
  "# mutate() adds a new column. A residual is how far each island sits above (+)",
  "# or below (-) the line: positive = more species than its area predicts.",
  "islands <- islands |>",
  if (logx) c(
    "  mutate(residual = residuals(model)) |>",
    sprintf("  filter(%s > 0)    # a log scale cannot show 0, so drop islands with 0", X)
  ) else "  mutate(residual = residuals(model))",
  "",
  "# Plot the residuals against the other variable with ggplot2",
  sprintf("ggplot(islands, aes(x = %s, y = residual)) +", X),
  "  geom_hline(yintercept = 0, linetype = \"dashed\") +   # 0 = exactly as predicted",
  "  geom_point(colour = \"#6B8F9C\", size = 2.5) +",
  "  geom_smooth(method = \"lm\", formula = y ~ x,          # trend line with its 95% band",
  "              colour = \"#C55A11\", fill = \"#F4B183\") +",
  if (logx) "  scale_x_log10() +",
  "  labs(y = \"More (+) or fewer (-) species than predicted\") +",
  "  theme_classic(base_size = 14)",
  "",
  "# Test the trend: fit a second straight line, residual explained by the variable",
  sprintf("model2 <- lm(residual ~ %s, data = islands)", if (logx) sprintf("log10(%s)", X) else X),
  "",
  "# Collect the result in a tidy table. A p-value below 0.05 means a significant trend.",
  "tibble(",
  "  slope     = coef(model2)[2],",
  "  p_value   = summary(model2)$coefficients[2, 4],",
  "  r_squared = summary(model2)$r.squared",
  ")"
)

code_pred_txt <- function(read_line, S, A, new_area, loss) code_text(
  "# Lines starting with # are comments: notes for people. R skips them.",
  "",
  "library(dplyr)",
  "",
  "# Read the data, keep islands with species and area above 0, and fit the species-area line",
  read_line,
  "islands <- islands |>",
  sprintf("  filter(%s > 0, %s > 0)", S, A),
  sprintf("model <- lm(log10(%s) ~ log10(%s), data = islands)", S, A),
  "",
  "# Store z (the slope) and c (10 to the power of the intercept) in a tidy table",
  "results <- tibble(",
  "  z = coef(model)[2],",
  "  c = 10^coef(model)[1]",
  ")",
  "",
  "# Predict the number of species on a new island with S = c * A^z.",
  "# ^ means 'to the power of'. Change new_area and run the code again.",
  sprintf("new_area <- %s", new_area),
  "tibble(area = new_area) |>",
  "  mutate(predicted_species = results$c * area^results$z)",
  "",
  "# Habitat loss: if a fraction of the habitat is destroyed, the fraction of",
  "# species that eventually remains is (1 - fraction lost)^z.",
  "# loss is a fraction: 0.5 means 50% of the habitat is destroyed.",
  sprintf("loss <- %s", loss),
  "tibble(habitat_lost = loss) |>",
  "  mutate(species_remaining = (1 - habitat_lost)^results$z,",
  "         species_lost      = 1 - species_remaining)"
)

